{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname } from 'node:path'

const __dirname = dirname(fileURLToPath(import.meta.url))

// Import merge logic
import { parseInput, computeMerge } from './merge.js'

const mode = process.argv[2]

if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}

// Read input from stdin
let input = ''
try {
  input = readFileSync(0, 'utf-8')
} catch (e) {
  // If reading fails, treat as empty
}

// Parse input
let docs
try {
  docs = parseInput(input)
} catch (e) {
  process.stderr.write(e.message + '\n')
  process.exit(2)
}

const [mine, base, theirs] = docs

// Compute merge
const result = computeMerge(mine, base, theirs, mode)

// Output
process.stdout.write(result.output)
process.exit(result.exitCode)
"}

