{"file_path":"src/merge.js","content":"/**
 * Core three-way merge algorithm.
 */

/**
 * Split the input into the three documents. Lines are split on newlines with
 * the empty tail a trailing newline leaves dropped; a line that is exactly
 * `%%%` separates the documents.
 */
export function parseInput(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const separators = []
  for (let i = 0; i < lines.length; i++) {
    if (lines[i] === '%%%') separators.push(i)
  }

  if (separators.length !== 2) {
    throw new Error('error: expected three parts separated by %%%')
  }

  return [
    lines.slice(0, separators[0]),
    lines.slice(separators[0] + 1, separators[1]),
    lines.slice(separators[1] + 1),
  ]
}

/**
 * Table of longest common subsequence lengths of the suffixes of `doc` and
 * `base`: table[i][j] is the length for doc[i..] and base[j..].
 */
function lcsTable(doc, base) {
  const n = doc.length
  const m = base.length
  const table = []
  for (let i = 0; i <= n; i++) table.push(new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      table[i][j] = doc[i] === base[j]
        ? table[i + 1][j + 1] + 1
        : Math.max(table[i + 1][j], table[i][j + 1])
    }
  }
  return table
}

/**
 * The matches of the longest common subsequence, taking the one whose matches
 * come earliest: match whenever the current lines are equal, otherwise advance
 * the side whose remaining subsequence is at least as long as the other's,
 * preferring the base on a tie.
 */
function lcsMatches(doc, base) {
  const table = lcsTable(doc, base)
  const matches = []
  let i = 0
  let j = 0
  while (i < doc.length && j < base.length) {
    if (doc[i] === base[j]) {
      matches.push({ docIdx: i, baseIdx: j })
      i++
      j++
    } else if (table[i][j + 1] >= table[i + 1][j]) {
      j++
    } else {
      i++
    }
  }
  return matches
}

/**
 * Every stretch the subsequence does not cover, as a run of base lines
 * replaced by a run of the side's lines.
 */
function diff(doc, base) {
  const matches = lcsMatches(doc, base)
  const changes = []
  let docIdx = 0
  let baseIdx = 0

  const push = (docEnd, baseEnd) => {
    if (docIdx < docEnd || baseIdx < baseEnd) {
      changes.push({ baseStart: baseIdx, baseEnd, docStart: docIdx, docEnd })
    }
  }

  for (const match of matches) {
    push(match.docIdx, match.baseIdx)
    docIdx = match.docIdx + 1
    baseIdx = match.baseIdx + 1
  }
  push(doc.length, base.length)

  return changes
}

/** The lines a side holds for the base range [start, end) of a region. */
function sideLines(doc, base, changes, start, end) {
  if (changes.length === 0) return base.slice(start, end)
  let sideStart = Infinity
  let sideEnd = -Infinity
  let docStart = Infinity
  let docEnd = -Infinity
  for (const change of changes) {
    if (change.baseStart < sideStart) sideStart = change.baseStart
    if (change.baseEnd > sideEnd) sideEnd = change.baseEnd
    if (change.docStart < docStart) docStart = change.docStart
    if (change.docEnd > docEnd) docEnd = change.docEnd
  }
  return doc.slice(docStart - (sideStart - start), docEnd + (end - sideEnd))
}

function sameLines(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

/**
 * The regions of the merge, in order.
 */
export function mergeRegions(mine, base, theirs) {
  const mineChanges = diff(mine, base).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = diff(theirs, base).map(c => ({ ...c, side: 'theirs' }))

  const all = [...mineChanges, ...theirsChanges]
  all.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let pos = 0
  let index = 0

  while (index < all.length) {
    const first = all[index]
    const start = first.baseStart
    let end = first.baseEnd
    const group = [first]
    index++
    while (index < all.length && all[index].baseStart <= end) {
      if (all[index].baseEnd > end) end = all[index].baseEnd
      group.push(all[index])
      index++
    }

    if (start > pos) {
      regions.push({ type: 'stable', lines: base.slice(pos, start) })
    }
    pos = end

    if (group.length === 1) {
      const only = group[0]
      regions.push({
        type: only.side,
        lines: (only.side === 'mine' ? mine : theirs).slice(only.docStart, only.docEnd),
      })
      continue
    }

    const mineLines = sideLines(mine, base, group.filter(c => c.side === 'mine'), start, end)
    const baseLines = base.slice(start, end)
    const theirsLines = sideLines(theirs, base, group.filter(c => c.side === 'theirs'), start, end)

    if (sameLines(mineLines, theirsLines)) {
      regions.push({ type: 'both', lines: mineLines })
    } else if (sameLines(mineLines, baseLines)) {
      regions.push({ type: 'theirs', lines: theirsLines })
    } else if (sameLines(theirsLines, baseLines)) {
      regions.push({ type: 'mine', lines: mineLines })
    } else {
      regions.push({ type: 'conflict', mineLines, baseLines, theirsLines })
    }
  }

  if (pos < base.length) {
    regions.push({ type: 'stable', lines: base.slice(pos) })
  }

  return regions
}

/** The output and exit code for a mode. */
export function render(regions, mode) {
  const out = []
  let conflicted = false

  for (const region of regions) {
    if (region.type === 'conflict') {
      conflicted = true
      if (mode === 'regions') {
        out.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
      } else {
        out.push('<<<<<<< mine', ...region.mineLines)
        if (mode === 'merge') out.push('||||||| base', ...region.baseLines)
        out.push('=======', ...region.theirsLines, '>>>>>>> theirs')
      }
    } else if (mode === 'regions') {
      out.push(`${region.type} ${region.lines.length}`)
    } else {
      out.push(...region.lines)
    }
  }

  return {
    output: out.map(line => `${line}\n`).join(''),
    exitCode: conflicted ? 1 : 0,
  }
}

export function computeMerge(mine, base, theirs, mode) {
  return render(mergeRegions(mine, base, theirs), mode)
}
"}

