  }

  const doc1 = lines.slice(0, separators[0])
  const doc2 = lines.slice(separators[0] + 1, separators[1])
  const doc3 = lines.slice(separators[1] + 1)

  return [doc1, doc2, doc3]
}

/**
 * Greedy LCS: find longest common subsequence using greedy algorithm
 * Returns array of indices into base that match doc
 */
function greedyLCS(doc, base) {
  const matches = []
  let docIdx = 0
  let baseIdx = 0

  while (docIdx < doc.length && baseIdx < base.length) {
    if (doc[docIdx] === base[baseIdx]) {
      matches.push({ docIdx, baseIdx })
      docIdx++
      baseIdx++
    } else {
      const docRemaining = doc.length - docIdx
      const baseRemaining = base.length - baseIdx

      // Advance the side whose remaining is >= the other's
      // Prefer to advance the base when they tie
      if (baseRemaining >= docRemaining) {
        baseIdx++
      } else {
        docIdx++
      }
    }
  }

  return matches
}

/**
 * Extract changes from LCS matches
 * A change is a run of base lines replaced by a run of doc lines
 */
function extractChanges(doc, base, matches) {
  if (matches.length === 0) {
    // No matches, all lines are changed
    if (base.length > 0 || doc.length > 0) {
      return [{
        baseStart: 0,
        baseEnd: base.length,
        docLines: doc
      }]
    }
    return []
  }

  const changes = []
  let docIdx = 0
  let baseIdx = 0

  for (let matchIdx = 0; matchIdx < matches.length; matchIdx++) {
    const match = matches[matchIdx]

    // Collect everything before this match
    if (docIdx < match.docIdx || baseIdx < match.baseIdx) {
      changes.push({
        baseStart: baseIdx,
        baseEnd: match.baseIdx,
        docLines: doc.slice(docIdx, match.docIdx)
      })
    }

    // Advance past the match
    docIdx = match.docIdx + 1
    baseIdx = match.baseIdx + 1
  }

  // Collect anything after the last match
  if (docIdx < doc.length || baseIdx < base.length) {
    changes.push({
      baseStart: baseIdx,
      baseEnd: base.length,
      docLines: doc.slice(docIdx)
    })
  }

  return changes
}

/**
 * Compute the merge result
 */
export function computeMerge(mine, base, theirs, mode) {
  // Compute changes for both sides
  const mineMatches = greedyLCS(mine, base)
  const theirsMatches = greedyLCS(theirs, base)

  const mineChanges = extractChanges(mine, base, mineMatches)
  const theirsChanges = extractChanges(theirs, base, theirsMatches)

  // Merge changes into regions
  const regions = mergeChanges(mine, base, theirs, mineChanges, theirsChanges)

  // Format output based on mode
  if (mode === 'regions') {
    return formatRegions(regions)
  } else if (mode === 'merge') {
    return formatMerge(regions, false)
  } else if (mode === 'merge2') {
    return formatMerge(regions, true)
  }
}

/**
 * Merge changes into regions
 */
function mergeChanges(mine, base, theirs, mineChanges, theirsChanges) {
  const regions = []

  // Create a combined list of changes with their origin
  const allChanges = [
    ...mineChanges.map(c => ({ ...c, side: 'mine' })),
    ...theirsChanges.map(c => ({ ...c, side: 'theirs' }))
  ]

  // Sort by baseStart, then by side (mine before theirs)
  allChanges.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === 'mine' && b.side === 'theirs') return -1
    if (a.side === 'theirs' && b.side === 'mine') return 1
    return 0
  })

  let currentRegionStart = 0
  let currentRegionEnd = 0
  let changeIdx = 0

  while (changeIdx < allChanges.length) {
    const change = allChanges[changeIdx]

    // Start a new region
    currentRegionStart = change.baseStart
    currentRegionEnd = change.baseEnd

    const regionChanges = [change]
    changeIdx++

    // Absorb following changes that start at or before current region end
    while (changeIdx < allChanges.length) {
      const nextChange = allChanges[changeIdx]
      if (nextChange.baseStart <= currentRegionEnd) {
        regionChanges.push(nextChange)
        currentRegionEnd = Math.max(currentRegionEnd, nextChange.baseEnd)
        changeIdx++
      } else {
        break
      }
    }

    // Resolve this region
    const resolved = resolveRegion(
      mine, base, theirs,
      currentRegionStart, currentRegionEnd,
      regionChanges
    )

    // Add stable region before this region if needed
    if (currentRegionStart > 0 && (regions.length === 0 || regions[regions.length - 1].baseEnd < currentRegionStart)) {
      const stableEnd = currentRegionStart
      const stableStart = regions.length === 0 ? 0 : regions[regions.length - 1].baseEnd
      regions.push({
        type: 'stable',
        baseStart: stableStart,
        baseEnd: stableEnd,
        lines: base.slice(stableStart, stableEnd)
      })
    }

    regions.push(resolved)
  }

  // Add final stable region if needed
  const lastRegionEnd = regions.length > 0 ? regions[regions.length - 1].baseEnd : 0
  if (lastRegionEnd < base.length) {
    regions.push({
      type: 'stable',
      baseStart: lastRegionEnd,
      baseEnd: base.length,
      lines: base.slice(lastRegionEnd)
    })
  }

  return regions
}

/**
 * Resolve a region with one or more changes
 */
function resolveRegion(mine, base, theirs, regionBaseStart, regionBaseEnd, changes) {
  // Group changes by side
  const mineChanges = changes.filter(c => c.side === 'mine')
  const theirsChanges = changes.filter(c => c.side === 'theirs')

  // If only one side has changes, use that side
  if (mineChanges.length === 0) {
    const lines = []
    for (const change of theirsChanges) {
      lines.push(...change.docLines)
    }
    return {
      type: 'theirs',
      baseStart: regionBaseStart,
      baseEnd: regionBaseEnd,
      lines: lines
    }
  }

  if (theirsChanges.length === 0) {
    const lines = []
    for (const change of mineChanges) {
      lines.push(...change.docLines)
    }
    return {
      type: 'mine',
      baseStart: regionBaseStart,
      baseEnd: regionBaseEnd,
      lines: lines
    }
  }

  // Both sides have changes
  const mineLines = reconstructLines(mine, regionBaseStart, regionBaseEnd, mineChanges)
  const baseLines = base.slice(regionBaseStart, regionBaseEnd)
  const theirsLines = reconstructLines(theirs, regionBaseStart, regionBaseEnd, theirsChanges)

  // Check if both sides made the same change
  if (JSON.stringify(mineLines) === JSON.stringify(theirsLines)) {
    return {
      type: 'both',
      baseStart: regionBaseStart,
      baseEnd: regionBaseEnd,
      lines: mineLines
    }
  }

  // Check if mine equals base (theirs wins)
  if (JSON.stringify(mineLines) === JSON.stringify(baseLines)) {
    return {
      type: 'theirs',
      baseStart: regionBaseStart,
      baseEnd: regionBaseEnd,
      lines: theirsLines
    }
  }

  // Check if theirs equals base (mine wins)
  if (JSON.stringify(theirsLines) === JSON.stringify(baseLines)) {
    return {
      type: 'mine',
      baseStart: regionBaseStart,
      baseEnd: regionBaseEnd,
      lines: mineLines
    }
  }

  // Otherwise it's a conflict
  return {
    type: 'conflict',
    baseStart: regionBaseStart,
    baseEnd: regionBaseEnd,
    mineLines: mineLines,
    theirsLines: theirsLines,
    baseLines: baseLines
  }
}

/**
 * Reconstruct lines for a side in a region
 */
function reconstructLines(doc, regionBaseStart, regionBaseEnd, changes) {
  // Changes contain the lines that doc has in place of base lines
  // We need to rebuild what doc has in the region [regionBaseStart, regionBaseEnd)

  const lines = []

  // For each change, add its doc lines
  for (const change of changes) {
    lines.push(...change.docLines)
  }

  return lines
}

/**
 * Format output for regions mode
 */
function formatRegions(regions) {
  let output = ''
  let hasConflict = false

  for (const region of regions) {
    if (region.type === 'stable') {
      output += `stable ${region.lines.length}\n`
    } else if (region.type === 'mine') {
      output += `mine ${region.lines.length}\n`
    } else if (region.type === 'theirs') {
      output += `theirs ${region.lines.length}\n`
    } else if (region.type === 'both') {
      output += `both ${region.lines.length}\n`
    } else if (region.type === 'conflict') {
      hasConflict = true
      output += `conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}\n`
    }
  }

  return {
    output,
    exitCode: hasConflict ? 1 : 0
  }
}

/**
 * Format output for merge or merge2 mode
 */
function formatMerge(regions, omitBase) {
  let output = ''
  let hasConflict = false

  for (const region of regions) {
    if (region.type === 'conflict') {
      hasConflict = true
      output += '<<<<<<< mine\n'
      output += region.mineLines.map(line => line + '\n').join('')
      if (!omitBase) {
        output += '||||||| base\n'
        output += region.baseLines.map(line => line + '\n').join('')
      }
      output += '=======\n'
      output += region.theirsLines.map(line => line + '\n').join('')
      output += '>>>>>>> theirs\n'
    } else {
      output += region.lines.map(line => line + '\n').join('')
    }
  }

  return {
    output,
    exitCode: hasConflict ? 1 : 0
  }
}

